{"file_path":"src/lib.rs","content":"pub struct Luhn {
    code: String,
}

impl Luhn {
    pub fn is_valid(&self) -> bool {
        let mut digit_count = 0;
        let mut sum = 0;

        for c in self.code.chars().rev() {
            if c.is_ascii_digit() {
                let mut d = c.to_digit(10).unwrap();
                if digit_count % 2 == 1 {
                    d *= 2;
                    if d > 9 {
                        d -= 9;
                    }
                }
                sum += d;
                digit_count += 1;
            } else if c != ' ' {
                return false;
            }
        }

        digit_count > 1 && sum % 10 == 0
    }
}

impl<T: ToString> From<T> for Luhn {
    fn from(input: T) -> Self {
        Luhn {
            code: input.to_string(),
        }
    }
}
"}

